from collections import deque

def solve():
    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        dialog = input().strip()
        queue = deque()

        for i in range(n):
            if dialog[i] == "Q":
                queue.append("Q")
            elif dialog[i] == "A":
                if not queue:
                    print("No")
                    break
                else:
                    queue.popleft()
        else:
            if not queue:
                print("Yes")
            else:
                print("No")

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    t = int(data[idx])
    idx += 1
    results = []
    for _ in range(t):
        n = int(data[idx])
        idx += 1
        a = list(map(int, data[idx:idx+n]))
        idx += n
        s = data[idx]
        idx += 1
        num_to_char = {}
        char_to_num = {}
        can = True
        for num, ch in zip(a, s):
            if num in num_to_char:
                if num_to_char[num] != ch:
                    can = False
                    break
            else:
                num_to_char[num] = ch
            if ch in char_to_num:
                if char_to_num[ch] != num:
                    can = False
                    break
            else:
                char_to_num[ch] = num
        results.append("YES" if can else "NO")
    print('\n'.join(results))

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input().strip()
        i = 0
        press_num = 1  # 1-indexed total key presses
        possible = True
        while i < n:
            if press_num % 2 == 1:
                # Should be a single letter
                if i+1 < n and s[i] == s[i+1]:
                    possible = False
                    break
                i += 1
            else:
                # Should be two same letters
                if i+1 >= n or s[i] != s[i+1]:
                    possible = False
                    break
                i += 2
            press_num += 1
        print("YES" if possible else "NO")

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    cases = data[1:]

    def size_value(s):
        return (
            {'S': 0, 'M': 1, 'L': 2}[s[-1]],
            -len(s) if s[-1] == 'S' else (0 if s[-1] == 'M' else len(s))
        )

    result = []
    for i in range(t):
        a, b = cases[2*i], cases[2*i+1]
        va, vb = size_value(a), size_value(b)
        result.append('<=>[va>vb]-[va<vb]+='[va>vb]-[va<vb] and '>' or va<vb and '<' or '=')
    print('\n'.join(
        ('=' if va == vb else ('<' if va < vb else '>'))
        for i in range(t)
        for a, b in [(cases[2*i], cases[2*i+1])]
        for va, vb in [ (size_value(a), size_value(b)) ]
    ))

def solve(n, a):
    import sympy as sp
    b = list(range(1, n+1))
    idx = [sp.Indexed解(Frozenset(a), i) for i in range(n)]
    for i in idx:
        b[i] = b[sp.Indexed解(Frozenset(a), i) + 1]
    return tuple(b)

