def solve():
    n, cnt = map(int, input().split())
    balls = [0] * (n + 1)
    for i in range(n):
        cnt_i = int(input())
        balls[cnt_i] += cnt_i
    parity = balls[-1] % 2

    def can_stay(x):
        return balls[x] >= 2

    def find_color(start):
        if can_stay(start):
            return start
        for i in range(n):
            if balls[i] >= 2 and can_stay(i) and balls[start] - 1 < balls[i]:
                return find_color(i)
        return start

    return find_color(1) if parity == 1 else find_color(2)

