def solve(n, m, a, b):
    def can_win(n, a, m, b):
        dp = [[False] * (m + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            for j in range(m + 1):
                if j == 0:
                    dp[i][j] = (a[i] <= 0)
                elif a[i] > b[j-1]:
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = dp[i-1][j] or (not dp[i-1][j-1] and a[i] - b[j-1] > 0)
        return not dp[-1][-1]

